create or replace function public.create_club(p_name text,p_slug text,p_timezone text,p_idempotency_key uuid) returns uuid language plpgsql security definer set search_path=pg_catalog,public,private as $$ declare v_actor uuid:=public.current_player_id();v_club uuid;begin if v_actor is null then raise exception using errcode='P0001',detail='AUTH_REQUIRED';end if;insert into private.idempotency_commands(actor_id,operation,key,request_hash)values(v_actor,'create_club',p_idempotency_key,encode(extensions.digest(concat_ws('|',p_name,p_slug,p_timezone),'sha256'),'hex'))on conflict(actor_id,operation,key)do update set key=excluded.key returning (response->>'clubId')::uuid into v_club;if v_club is not null then return v_club;end if;insert into public.clubs(name,slug,timezone)values(trim(p_name),lower(trim(p_slug)),p_timezone)returning id into v_club;insert into public.club_memberships(club_id,player_id,role)values(v_club,v_actor,'owner');update private.idempotency_commands set response=jsonb_build_object('clubId',v_club)where actor_id=v_actor and operation='create_club' and key=p_idempotency_key;insert into private.audit_log(actor_auth_user_id,action,aggregate_type,aggregate_id,club_id)values(auth.uid(),'club.created','club',v_club,v_club);return v_club;end$$;
create or replace function public.set_membership_role(p_club_id uuid,p_membership_id uuid,p_role public.club_role,p_reason text,p_idempotency_key uuid) returns bigint language plpgsql security definer set search_path=pg_catalog,public,private as $$ declare v_version bigint;v_old public.club_role;begin if not private.has_club_role(p_club_id,array['owner']::public.club_role[])then raise exception using errcode='P0001',detail='PERMISSION_DENIED';end if;select role into v_old from public.club_memberships where id=p_membership_id and club_id=p_club_id for update;if v_old='owner' and p_role<>'owner' and (select count(*) from public.club_memberships where club_id=p_club_id and role='owner' and status='active')=1 then raise exception using errcode='P0001',detail='INVALID_STATE_TRANSITION';end if;update public.club_memberships set role=p_role where id=p_membership_id returning version+1 into v_version;insert into private.audit_log(actor_auth_user_id,action,aggregate_type,aggregate_id,club_id,before_state,after_state,request_id)values(auth.uid(),'membership.role_changed','membership',p_membership_id,p_club_id,jsonb_build_object('role',v_old),jsonb_build_object('role',p_role),p_idempotency_key);return v_version;end$$;
create or replace function public.set_club_subscription_webhook(p_club_id uuid,p_status public.subscription_status,p_valid_until timestamptz,p_event_id text) returns void language plpgsql security definer set search_path=pg_catalog,public,private as $$ begin update public.clubs set subscription_status=p_status,subscription_valid_until=p_valid_until where id=p_club_id;insert into private.audit_log(action,aggregate_type,aggregate_id,club_id,after_state)values('subscription.updated','club',p_club_id,p_club_id,jsonb_build_object('status',p_status,'eventId',p_event_id));end$$;
revoke all on function public.create_club(text,text,text,uuid),public.set_membership_role(uuid,uuid,public.club_role,text,uuid) from public;grant execute on function public.create_club(text,text,text,uuid),public.set_membership_role(uuid,uuid,public.club_role,text,uuid) to authenticated;
revoke all on function public.set_club_subscription_webhook(uuid,public.subscription_status,timestamptz,text) from public,anon,authenticated;
grant execute on function public.set_club_subscription_webhook(uuid,public.subscription_status,timestamptz,text) to service_role;
